+            }
+            return true;
+        }
+        if (!storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        return false;
+    }
+
+    private Properties loadRulesFrom(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private void createIndex(File storedRulesFile) {
+        try {
+            if (!storedRulesFile.createNewFile() && !Files.isRegularFile(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("Could not create store index");
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.find(rule.getDescription()) != null;
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            IndexEntry existing = storedRules.find(rule.getDescription());
+            if (existing == null && violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                return;
+            }
+
+            if (existing != null) {
+                Path ruleFile = validateExistingSavePath(existing.fileName);
+                if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                    forgetRule(existing, ruleFile);
+                } else {
+                    write(violations, ruleFile);
+                }
+                return;
+            }
+
+            String ruleFileName = createRuleFileName(rule.getDescription());
+            Path ruleFile = validateNewSavePath(ruleFileName);
+            write(violations, ruleFile);
+            storedRules.put(rule.getDescription(), ruleFileName);
+            try {
+                storedRules.syncFileSystem();
+            } catch (RuntimeException e) {
+                try {
+                    Files.deleteIfExists(ruleFile);
+                } catch (IOException ignored) {
+                    // The original update exception is more useful to callers.
+                }
+                throw e;
+            }
+        }
+    }
+
+    private String createRuleFileName(String description) {
+        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (result == null || result.isEmpty()) {
+            throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
+        }
+        return result;
+    }
+
+    private Path validateNewSavePath(String fileName) {
+        Path path = validateSavePath(fileName);
+        if (storedRules.containsFileName(fileName)) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name is already recorded: %s", fileName));
+        }
+        if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name is already occupied: %s", fileName));
+        }
+        return path;
+    }
+
+    private Path validateExistingSavePath(String fileName) {
+        return validateSavePath(fileName);
+    }
+
+    private Path validateSavePath(String fileName) {
+        Path path = resolvePath(fileName);
+        if (path == null || !isLexicallyDirect(path)) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name does not lead directly into the store folder: %s", fileName));
+        }
+        Path index = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME).toAbsolutePath().normalize();
+        if (path.equals(index) || sameFile(path, index)) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name leads to the store index: %s", fileName));
+        }
+        if (Files.exists(path, LinkOption.NOFOLLOW_LINKS) && !isDirectFile(path)) {
+            throw new StoreUpdateFailedException(String.format("Rule violation file name does not lead directly into the store folder: %s", fileName));
+        }
+        return path;
+    }
+
+    private void forgetRule(IndexEntry entry, Path ruleFile) {
+        boolean shared = storedRules.entries().stream()
+                .filter(other -> !other.key.equals(entry.key))
+                .anyMatch(other -> sameEntryFile(entry.fileName, other.fileName));
+        if (!shared) {
+            try {
+                deleteNamedFile(ruleFile);
+            } catch (IOException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules.remove(entry.key);
+        storedRules.syncFileSystem();
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8));
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            IndexEntry entry = storedRules.find(rule.getDescription());
+            checkArgument(entry != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(entry.fileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return ensureUnixLineBreaks(new String(toByteArray(new File(storeFolder, fileName)), UTF_8));
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private IntegrityInspection inspect(File folder, File index, Properties properties) {
+        List<IndexEntry> entries = properties.entrySet().stream()
+                .filter(entry -> entry.getKey() instanceof String && entry.getValue() instanceof String)
+                .map(entry -> new IndexEntry((String) entry.getKey(), (String) entry.getValue()))
+                .sorted(Comparator.comparing(entry -> entry.key))
+                .collect(toList());
+        Path folderPath = folder.toPath();
+        Path folderAbsolute = folderPath.toAbsolutePath().normalize();
+        Path folderReal = realPath(folderPath);
+        Path indexPath = index.toPath().toAbsolutePath().normalize();
+
+        for (IndexEntry entry : entries) {
+            entry.path = resolvePath(folderAbsolute, entry.fileName);
+            entry.broken = entry.path == null || !isDirectFile(entry.path, folderAbsolute, folderReal);
+            entry.resolved = !entry.broken && containsOnlyLineBreaks(entry.path);
+            entry.derivedFileName = createRuleFileName(entry.key);
+            entry.misplaced = !entry.fileName.equals(entry.derivedFileName);
+        }
+
+        markShared(entries);
+        Map<String, Integer> derivedCounts = new HashMap<>();
+        for (IndexEntry entry : entries) {
+            derivedCounts.put(entry.derivedFileName, derivedCounts.getOrDefault(entry.derivedFileName, 0) + 1);
+        }
+        for (IndexEntry entry : entries) {
+            entry.colliding = derivedCounts.get(entry.derivedFileName) > 1;
+            entry.occupied = !entry.fileName.equals(entry.derivedFileName)
+                    && (isOccupiedDerivedName(entry.derivedFileName, entries, folderAbsolute, folderReal, indexPath));
+        }
+
+        List<Path> unownedFiles = findUnownedFiles(folderPath, indexPath, entries);
+        return new IntegrityInspection(entries, unownedFiles);
+    }
+
+    private boolean isOccupiedDerivedName(String derived, List<IndexEntry> entries, Path folderAbsolute, Path folderReal, Path indexPath) {
+        if (entries.stream().anyMatch(entry -> entry.fileName.equals(derived))) {
+            return true;
+        }
+        Path derivedPath = resolvePath(folderAbsolute, derived);
+        if (derivedPath == null || !isLexicallyDirect(derivedPath, folderAbsolute)) {
+            return true;
+        }
+        if (derivedPath.equals(indexPath) || sameFile(derivedPath, indexPath)) {
+            return true;
+        }
+        return Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private List<Path> findUnownedFiles(Path folder, Path index, List<IndexEntry> entries) {
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(folder)) {
+            for (Path child : children) {
+                if (child.toAbsolutePath().normalize().equals(index.toAbsolutePath().normalize())) {
+                    continue;
+                }
+                if (!Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = entries.stream().anyMatch(entry -> entry.path != null && sameFile(entry.path, child));
+                if (!owned) {
+                    result.add(child);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private void markShared(List<IndexEntry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                IndexEntry first = entries.get(i);
+                IndexEntry second = entries.get(j);
+                if (first.fileName.equals(second.fileName) || sameEntryFile(first.fileName, second.fileName)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private boolean sameEntryFile(String first, String second) {
+        Path firstPath = resolvePath(first);
+        Path secondPath = resolvePath(second);
+        return first.equals(second) || firstPath != null && secondPath != null && sameFile(firstPath, secondPath);
+    }
+
+    private void repair(File folder, File index, FileSyncedProperties rules, IntegrityInspection inspection) {
+        boolean changed = false;
+        for (IndexEntry entry : inspection.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                rules.remove(entry.key);
+                changed = true;
+            } else if (entry.resolved) {
+                try {
+                    if (!isIndexPath(entry.path, index.toPath())) {
+                        deleteNamedFile(entry.path);
+                    }
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                rules.remove(entry.key);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                Path destination = resolvePath(folder.toPath().toAbsolutePath().normalize(), entry.derivedFileName);
+                try {
+                    Path source = Files.isSymbolicLink(entry.path) ? entry.path.toRealPath() : entry.path;
+                    Files.move(source, destination);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                rules.put(entry.key, entry.derivedFileName);
+                changed = true;
+            }
+        }
+        if (changed) {
+            rules.syncFileSystem();
+        }
+    }
+
+    private boolean isIndexPath(Path path, Path index) {
+        return path != null && (path.toAbsolutePath().normalize().equals(index.toAbsolutePath().normalize()) || sameFile(path, index));
+    }
+
+    private void deleteNamedFile(Path path) throws IOException {
+        if (path == null || !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            return;
+        }
+        if (Files.isSymbolicLink(path)) {
+            Path target = path.toRealPath();
+            if (!Files.isRegularFile(target)) {
+                throw new IOException("Not a regular file: " + path);
+            }
+            Files.delete(target);
+            Files.delete(path);
+        } else {
+            if (!Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("Not a regular file: " + path);
+            }
+            Files.delete(path);
+        }
+    }
+
+    private boolean containsOnlyLineBreaks(Path path) {
+        try {
+            byte[] bytes = Files.readAllBytes(path);
+            for (byte aByte : bytes) {
+                if (aByte != '\n' && aByte != '\r') {
+                    return false;
+                }
+            }
+            return true;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Path resolvePath(String fileName) {
+        return resolvePath(storeFolder.toPath().toAbsolutePath().normalize(), fileName);
+    }
+
+    private Path resolvePath(Path folderAbsolute, String fileName) {
+        try {
+            return folderAbsolute.resolve(Paths.get(fileName)).normalize();
